DO $ddl$ DECLARE s text;BEGIN s:=pg_get_functiondef('public._punch_core(uuid,uuid,double precision,double precision,double precision,text,timestamptz,text,text)'::regprocedure);s:=replace(s,'  ELSIF v_next_boundary IS NOT NULL AND v_next_boundary - v_eff <= interval ''2 hours'' THEN'||chr(10)||'    v_shift_start := v_next_boundary; v_early := v_next_boundary - v_eff;','');EXECUTE s;END $ddl$;